components.css:
.ds-btn-lamp {
  font-family: var(--font-ui, 'Inter Variable', Inter, system-ui, sans-serif);
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border-radius: var(--r-md, 8px);
  cursor: pointer;
  background: var(--lamp, #f0d9a8);
  color: var(--void, #0b0f0e);
  border: 1px solid var(--lamp, #f0d9a8);
  transition:
    background var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    border-color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}
.ds-btn-lamp:hover {
  background: var(--lamp-dim, #d4bc89);
  border-color: var(--lamp-dim, #d4bc89);
}
.ds-btn-lamp:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(240,217,168,0.35);
}

.ds-btn-ghost {
  font-family: var(--font-ui, 'Inter Variable', Inter, system-ui, sans-serif);
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border-radius: var(--r-md, 8px);
  cursor: pointer;
  background: transparent;
  color: var(--text-bright, #f2ece1);
  border: 1px solid var(--hairline, rgba(255, 255, 255, 0.09));
  transition:
    background var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    border-color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}
.ds-btn-ghost:hover {
  border-color: var(--edge-light, rgba(255, 255, 255, 0.06));
  background: var(--raised, #1a2220);
}
.ds-btn-ghost:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(240,217,168,0.35);
}

.ds-import-panel {
  margin: 1rem 0;
  padding: 1.5rem;
  max-width: 640px;
  background: var(--raised, #1a2220);
  border-radius: var(--r-lg, 14px);
  border-top: 1px solid var(--edge-light, rgba(255, 255, 255, 0.06));
}
.ds-panel-title {
  font-family: var(--font-display, 'Fraunces Variable', Fraunces, Georgia, serif);
  font-size: 1.15rem;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
  color: var(--text-bright, #f2ece1);
  margin: 0 0 0.75rem;
}
.ds-panel-body {
  font-family: var(--font-ui, 'Inter Variable', Inter, system-ui, sans-serif);
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--text-muted, #8e877c);
  margin: 0;
}

.ds-dropdown {
  position: relative;
  display: inline-block;
}
.ds-dropdown-button {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 9rem;
  justify-content: space-between;
  text-align: left;
  font-family: var(--font-ui, 'Inter Variable', Inter, system-ui, sans-serif);
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  padding: 0.5rem 1rem;
  border: 1px solid var(--hairline, rgba(255, 255, 255, 0.09));
  border-radius: var(--r-md, 8px);
  background: var(--raised, #1a2220);
  color: var(--text, #cfc8bc);
  cursor: pointer;
  transition:
    background var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    border-color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}
.ds-dropdown-button::after {
  content: '';
  width: 0.4rem;
  height: 0.4rem;
  border-right: 1.5px solid var(--text-muted, #8e877c);
  border-bottom: 1.5px solid var(--text-muted, #8e877c);
  transform: translateY(-0.15rem) rotate(45deg);
  transition: transform var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}
.ds-dropdown.is-open .ds-dropdown-button::after {
  transform: translateY(0.1rem) rotate(225deg);
}
.ds-dropdown-button:hover {
  background: var(--raised, #1a2220);
  color: var(--text-bright, #f2ece1);
  border-color: var(--edge-light, rgba(255, 255, 255, 0.06));
}
.ds-dropdown-button:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(240,217,168,0.35);
}
.ds-dropdown-list {
  position: absolute;
  top: calc(100% + 0.35rem);
  left: 0;
  z-index: 4;
  min-width: 100%;
  margin: 0;
  padding: 0.25rem;
  list-style: none;
  background: var(--raised, #1a2220);
  border: 1px solid var(--hairline, rgba(255, 255, 255, 0.09));
  border-radius: var(--r-md, 8px);
  box-shadow: var(--shadow-popover, 0 12px 32px rgba(0, 0, 0, 0.5));
}
.ds-dropdown-option {
  padding: 0.4rem 0.6rem;
  border-radius: var(--r-sm, 4px);
  color: var(--text, #cfc8bc);
  cursor: pointer;
  white-space: nowrap;
}
.ds-dropdown-option:hover {
  color: var(--text-bright, #f2ece1);
}
.ds-dropdown-option.ds-active {
  background: var(--room, #121816);
  color: var(--text-bright, #f2ece1);
}
.ds-dropdown-option.is-selected {
  color: var(--text-bright, #f2ece1);
  font-weight: 600;
}

.ds-segmented {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem;
  border: 1px solid var(--hairline, rgba(255, 255, 255, 0.09));
  border-radius: var(--r-pill, 999px);
  background: var(--room, #121816);
}
.ds-segmented-indicator {
  position: absolute;
  top: 0.25rem;
  left: 0;
  height: calc(100% - 0.5rem);
  border-radius: var(--r-pill, 999px);
  background: var(--raised, #1a2220);
  transition: transform var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
  pointer-events: none;
}
.ds-segmented-option {
  position: relative;
  z-index: 1;
  border: none;
  border-radius: var(--r-pill, 999px);
  background: transparent;
  color: var(--text-muted, #8e877c);
  padding: 0.35rem 0.9rem;
  font-family: var(--font-ui, 'Inter Variable', Inter, system-ui, sans-serif);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition:
    background var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}
.ds-segmented-option:hover:not(.is-selected) {
  background: transparent;
  border-color: transparent;
  color: var(--text, #cfc8bc);
}
.ds-segmented-option.is-selected {
  background: transparent;
  color: var(--text-bright, #f2ece1);
}
.ds-segmented-option:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(240,217,168,0.35);
}

.ds-level-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.ds-level-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.15rem;
  flex: 1 1 11rem;
  min-width: 11rem;
  max-width: 16rem;
  padding: 0.75rem 0.9rem;
  text-align: left;
  border: 1px solid var(--hairline, rgba(255, 255, 255, 0.09));
  border-radius: var(--r-lg, 14px);
  background: var(--room, #121816);
  color: var(--text-muted, #8e877c);
  font-family: var(--font-ui, 'Inter Variable', Inter, system-ui, sans-serif);
  font-weight: 400;
  cursor: pointer;
  transition:
    background var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    border-color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}
.ds-level-card:hover:not(.is-selected) {
  background: var(--room, #121816);
  border-color: var(--edge-light, rgba(255, 255, 255, 0.06));
  color: var(--text, #cfc8bc);
}
.ds-level-card:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(240,217,168,0.35);
}
.ds-level-card.is-selected {
  background: var(--raised, #1a2220);
  border-color: var(--edge-light, rgba(255, 255, 255, 0.06));
  color: var(--text, #cfc8bc);
}
.ds-level-elo {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 1.5rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
  color: var(--text-muted, #8e877c);
}
.ds-level-card.is-selected .ds-level-elo {
  color: var(--text-bright, #f2ece1);
}
.ds-level-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text, #cfc8bc);
}
.ds-level-card.is-selected .ds-level-name {
  color: var(--text-bright, #f2ece1);
}
.ds-level-blurb {
  font-size: 0.8rem;
  line-height: 1.4;
  color: var(--text-muted, #8e877c);
}

.ds-score-row {
  padding: 0.25rem 0 0.25rem 0.5rem;
  border-left: 1px solid transparent;
  border-radius: var(--r-sm, 4px);
  cursor: pointer;
  transition: border-color var(--t-state, 150ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}
.ds-score-row:hover .ds-san {
  color: var(--text-bright, #f2ece1);
}
.ds-score-row:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(240,217,168,0.35);
}
.ds-score-row.active {
  border-left-color: var(--lamp, #f0d9a8);
}
.ds-score-row.active .ds-san {
  color: var(--text-bright, #f2ece1);
}
.ds-san {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: var(--text, #cfc8bc);
}
.ds-annotation {
  margin: 0.5rem 0 1rem 0;
  padding-left: 1rem;
  border-left: 2px solid var(--hairline, rgba(255, 255, 255, 0.09));
}
.ds-score-row.is-inaccuracy .ds-annotation {
  border-left-color: var(--verdict-inaccuracy, #d9a441);
}
.ds-score-row.is-mistake .ds-annotation {
  border-left-color: var(--verdict-mistake, #e07a3c);
}
.ds-score-row.is-blunder .ds-annotation {
  border-left-color: var(--verdict-blunder, #e0524a);
}
.ds-verdict {
  display: block;
  font-family: var(--font-ui, 'Inter Variable', Inter, system-ui, sans-serif);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  margin-bottom: 0.25rem;
}
.ds-score-row.is-inaccuracy .ds-verdict {
  color: var(--verdict-inaccuracy, #d9a441);
}
.ds-score-row.is-mistake .ds-verdict {
  color: var(--verdict-mistake, #e07a3c);
}
.ds-score-row.is-blunder .ds-verdict {
  color: var(--verdict-blunder, #e0524a);
}
.ds-annotation-text {
  font-family: var(--font-display, 'Fraunces Variable', Fraunces, Georgia, serif);
  font-size: 1.15rem;
  font-weight: 400;
  line-height: 1.6;
  color: var(--text, #cfc8bc);
  margin: 0;
  max-width: 64ch;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.ds-score-row.active .ds-annotation-text {
  -webkit-line-clamp: unset;
  overflow: visible;
}
.ds-best-line {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 0.9rem;
  font-variant-numeric: tabular-nums;
  color: var(--text-muted, #8e877c);
  margin: 0.5rem 0 0;
}
.ds-score-row:not(.active) .ds-best-line {
  display: none;
}

.ds-evalbar {
  width: 14px;
  background: var(--board-dark, #4a5a52);
  position: relative;
  border-radius: var(--r-md, 8px);
  overflow: hidden;
}
.ds-evalfill {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--board-light, #b3bfb6);
  height: 50%;
  transition: height var(--t-piece, 240ms) var(--ease, cubic-bezier(0.16, 1, 0.3, 1));
}

.ds-readout {
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
  color: var(--lamp-dim, #d4bc89);
  text-align: center;
  min-height: 1.2rem;
  margin-top: 0.75rem;
}
